create trigger sp_protect_profile before insert or update on public.profiles for each row execute function public.sp_protect_profile();
create or replace function pg_temp.as_user(u uuid) returns void language plpgsql as $$ begin perform set_config('request.jwt.claim.sub', u::text, false); execute 'set role authenticated'; end $$;
create or replace function pg_temp.reset_user() returns void language plpgsql as $$ begin execute 'reset role'; perform set_config('request.jwt.claim.sub', '', false); end $$;
do $$ declare A uuid := '00000000-0000-0000-0000-0000000000a1'; C uuid := '00000000-0000-0000-0000-0000000000c1'; E uuid := '00000000-0000-0000-0000-0000000000e1'; N uuid := '00000000-0000-0000-0000-0000000000f1';
  v jsonb; ok boolean; r text;
begin
  perform pg_temp.as_user(C); update public.profiles set role = 'EDITOR' where id = C; perform pg_temp.reset_user();
  if (select role from public.profiles where id = C) <> 'CLIENT' then raise exception 'R1 FAIL'; end if; raise notice 'PASS R1 a client cannot make themselves an editor any more';
  perform pg_temp.as_user(E); update public.profiles set role = 'CLIENT' where id = E; perform pg_temp.reset_user();
  if (select role from public.profiles where id = E) <> 'EDITOR' then raise exception 'R2 FAIL'; end if; raise notice 'PASS R2 an editor cannot make themselves a client';
  perform pg_temp.as_user(N); update public.profiles set role = 'editor' where id = N; perform pg_temp.reset_user();
  if (select role from public.profiles where id = N) <> 'EDITOR' then raise exception 'R3 FAIL'; end if; raise notice 'PASS R3 a new person still chooses their role the first time (sign-up)';
  ok := false; perform pg_temp.as_user(C); begin perform public.sp_admin_set_role(E, 'CLIENT', 'good-pin'); exception when others then ok := sqlerrm ilike '%admins only%'; end; perform pg_temp.reset_user();
  if not ok then raise exception 'S1 FAIL'; end if; raise notice 'PASS S1 non-admins cannot use the role switch';
  ok := false; perform pg_temp.as_user(A); begin perform public.sp_admin_set_role(E, 'CLIENT', 'bad'); exception when others then ok := sqlerrm ilike '%pin%'; end; perform pg_temp.reset_user();
  if not ok then raise exception 'S2 FAIL'; end if; raise notice 'PASS S2 the admin needs the Admin PIN';
  perform pg_temp.as_user(A); v := public.sp_admin_set_role(E, 'client', 'good-pin'); perform pg_temp.reset_user();
  if (select role from public.profiles where id = E) <> 'CLIENT' or not (v->>'changed')::boolean then raise exception 'A1 FAIL %', v; end if;
  if not exists (select 1 from public.sp_admin_audit where action = 'role' and target_id = E::text and old_status = 'EDITOR' and new_status = 'CLIENT' and actor_id = A) then raise exception 'A1 FAIL audit'; end if;
  if not exists (select 1 from public.sp_notifications where user_id = E and title = 'Your account type changed') then raise exception 'A1 FAIL notification'; end if;
  raise notice 'PASS A1 admin + PIN switches Editor → Client (audit log + the person is notified)';
  perform pg_temp.as_user(A); perform public.sp_admin_set_role(E, 'EDITOR', 'good-pin'); perform pg_temp.reset_user();
  if (select role from public.profiles where id = E) <> 'EDITOR' then raise exception 'A2 FAIL'; end if; raise notice 'PASS A2 …and back to Editor';
  ok := false; perform pg_temp.as_user(A); begin perform public.sp_admin_set_role(C, 'ADMIN', 'good-pin'); exception when others then ok := sqlerrm ilike '%client or editor%'; end; perform pg_temp.reset_user();
  if not ok then raise exception 'A3 FAIL'; end if;
  ok := false; perform pg_temp.as_user(A); begin perform public.sp_admin_set_role(A, 'CLIENT', 'good-pin'); exception when others then ok := sqlerrm ilike '%own role%'; end; perform pg_temp.reset_user();
  if not ok then raise exception 'A3 FAIL own'; end if;
  raise notice 'PASS A3 nobody can be made admin this way, and an admin cannot change their own role';
  perform pg_temp.as_user(A); update public.profiles set role = 'CLIENT' where id = E; perform pg_temp.reset_user();
  if (select role from public.profiles where id = E) <> 'EDITOR' then raise exception 'A4 FAIL'; end if; raise notice 'PASS A4 even an admin cannot change roles by a plain edit — only through the PIN switch';
  if has_function_privilege('anon', 'public.sp_admin_set_role(uuid,text,text)', 'execute') then raise exception 'P1 FAIL'; end if; raise notice 'PASS P1 visitors cannot call the role switch';
end $$;
